import unittest

from hourglass.parsing import parse_span
from hourglass.models import Span
from hourglass.gaps import find_gaps, gap_label
from hourglass.errors import OutsideHoursError

OPEN = parse_span("08:00-18:00")
EDGE_GAPS = [
    "gap 08:00-09:00 (60 min)",
    "gap 12:00-14:00 (120 min)",
    "gap 15:00-18:00 (180 min)"
]


def spans(*texts):
    return [parse_span(text) for text in texts]


class FindGapsTests(unittest.TestCase):
    def test_midday_gap(self):
        worked = spans("08:00-12:00", "13:00-18:00")
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_no_workers_is_one_big_gap(self):
        self.assertEqual(
            find_gaps([], OPEN),
            ["gap 08:00-18:00 (600 min)"]
        )

    def test_full_cover_has_no_gaps(self):
        worked = spans("08:00-13:00", "12:00-18:00")
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_touching_spans_leave_no_gap(self):
        worked = spans("08:00-12:00", "12:00-18:00")
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_edges_and_unsorted_input(self):
        worked = spans("14:00-15:00", "09:00-12:00")
        self.assertEqual(find_gaps(worked, OPEN), EDGE_GAPS)

    def test_overlaps_do_not_hide_gaps(self):
        worked = spans("08:00-10:00", "09:00-11:00")
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 11:00-18:00 (420 min)"]
        )


class OutsideHoursTests(unittest.TestCase):
    def test_starts_too_early(self):
        with self.assertRaises(OutsideHoursError):
            find_gaps(spans("07:59-12:00"), OPEN)

    def test_ends_too_late(self):
        with self.assertRaises(OutsideHoursError):
            find_gaps(spans("12:00-18:01"), OPEN)

    def test_exactly_opening_hours_is_fine(self):
        self.assertEqual(find_gaps([OPEN], OPEN), [])


class LabelTests(unittest.TestCase):
    def test_label(self):
        self.assertEqual(
            gap_label(Span(720, 780)),
            "gap 12:00-13:00 (60 min)"
        )
